<script setup lang="ts">
import {computed,ref} from 'vue';import Panel from '../components/Panel.vue';import Workflow from '../components/Workflow.vue';import SealViewer from '../components/SealViewer.vue'
import {current,api,run,refresh,notify,busy,events,date} from '../store'
const model=computed(()=>current.value?.artifacts.filter(a=>a.kind==='stl').at(-1));const material=ref('光敏树脂');const mesh=ref(false);const mirrored=ref(false);const trial=ref(false);const comment=ref('')
const materials=[['光敏树脂','#c9aa83','精细原型制作'],['寿山石','#aa3e2d','传统篆刻材质'],['青田石','#839b7e','石质印章'],['黄铜','#c4a052','数控雕刻参考']]
const records=computed(()=>events.value.filter(e=>e.seal_id===current.value?.id&&e.action==='manufacturing'))
async function save(){await run(async()=>{if(!current.value||!model.value)throw new Error('请先生成真实STL模型');await api(`/seals/${current.value.id}/records`,{method:'POST',body:JSON.stringify({kind:'manufacturing',material:material.value,mesh_checked:mesh.value,mirror_checked:mirrored.value,physical_trial:trial.value,comment:comment.value,artifact_id:model.value.id})});await refresh();notify('实体制作记录已保存到数据库。')})}
</script>
<template><Panel class="workflow-panel top-workflow" title="实体制作流程" note="数字设计—三维输出—实体验证"><Workflow :active="4"/></Panel><div class="manufacture-grid"><Panel title="可制造模型与工艺参数" note="工艺链路清晰可追溯"><div class="manufacture-model"><SealViewer :url="model?.url"/></div><dl class="data-list"><div><dt>模型文件</dt><dd>{{model?model.id.slice(0,8)+'.stl':'尚未生成'}}</dd></div><div><dt>制造方式</dt><dd>3D打印 / CNC雕刻</dd></div><div><dt>印面规格</dt><dd>{{model?`${model.metadata.width_mm} × ${model.metadata.width_mm} mm`:'待生成'}}</dd></div><div><dt>关键检查</dt><dd>镜像 · 浮雕高度 · 最小线宽</dd></div></dl><a v-if="model" class="button primary full" :href="model.url" download>↓ 导出标准STL文件</a><RouterLink v-else class="button primary full" to="/reconstruction">前往生成STL模型</RouterLink></Panel><Panel title="材质与制造方案" note="多种印章与雕刻工艺"><div class="manufacture-materials"><button v-for="[name,color,hint] in materials" :key="name" @click="material=name" :class="{selected:material===name}"><span :style="{backgroundColor:color}"></span><b>{{name}}</b><small>{{hint}}</small></button></div><dl class="data-list"><div><dt>制造工艺参考</dt><dd>精度优先</dd></div></dl><p class="body-copy">导出后进行网格检查、切片预览、材料试制与实际试盖，验证印面结构是否可用。界面预览不表示材料强度或设备加工参数已验证。</p></Panel><Panel title="实际盖印验证" note="真实印迹才是最终效果依据"><div class="trial-placeholder"><img :src="current?.original_url||'/assets/restored.png'" alt="用于试盖对照的原始印谱"><span class="image-tag">{{current?'试盖对照原图':'对照参考 · 未试盖'}}</span></div><h3 class="material-title">工艺验证清单</h3><label class="param-row">模型闭合与法线<input type="checkbox" v-model="mesh" aria-label="已检查模型闭合与法线"></label><label class="param-row">盖印方向与镜像<input type="checkbox" v-model="mirrored" aria-label="已检查盖印方向与镜像"></label><label class="param-row">已完成实际试盖<input type="checkbox" v-model="trial" aria-label="已完成实际试盖"></label><textarea v-model="comment" placeholder="记录材料、切片设置、最小线宽和试盖结果；未试制请如实注明" aria-label="试盖记录" maxlength="3000"></textarea><button class="full" @click="save" :disabled="!model||busy">保存实体制作记录</button><p v-if="records[0]" class="hint">最近记录 {{date(records[0].created_at)}} · {{records[0].details.physical_trial?'用户报告已试盖':'尚未实际试盖'}}</p></Panel></div></template>
